package org.dextur.reputation.storage;

import java.time.*;
import java.util.*;
import org.dextur.reputation.api.*;
import org.dextur.reputation.domain.investigation.InvestigationData;
import org.dextur.reputation.domain.investigation.InvestigationData.*;
import org.dextur.reputation.domain.investigation.InvestigationData.Record;
import org.dextur.reputation.domain.protection.ProtectionData.*;

final class InvestigationReports {
    private final InvestigationSession s;
    InvestigationReports(InvestigationSession s){this.s=s;}
    Report read(Query q)throws Exception {
        long offset=Math.multiplyExact((long)q.page()-1,q.size());var summary=new TreeMap<String,String>();var rows=new ArrayList<Row>();long total=0;
        if(q.player()!=null){var p=s.profile(q.player(),q.scope());if(p==null)throw new IllegalArgumentException("INV_UNKNOWN");summary.putAll(InvestigationEngine.values(p,s.trust(q.player(),q.scope())));summary.put("uuid",q.player().toString());summary.put("updated",p.updatedAt().toString());}
        switch(q.section()){
            case INSPECT,RECALCULATE->{var p=s.profile(q.player(),q.scope());var a=s.administration(q.player(),q.scope());var recovery=s.recovery(q.player(),q.scope());var tier=s.tier(q.player(),q.scope());long admin=a==null?0:a.contribution();summary.put("administrative",Long.toString(admin));summary.put("system_recovery",Long.toString(Math.subtractExact(p.systemScore(),admin)));summary.put("recovery_reward",Long.toString(recovery==null?0:recovery.lifetimeReward()));summary.put("legacy_system",Long.toString(Math.subtractExact(Math.subtractExact(p.systemScore(),admin),recovery==null?0:recovery.lifetimeReward())));summary.put("voting_lock",Boolean.toString(a!=null&&a.votingLocked()));summary.put("overrides",Integer.toString(a==null?0:a.overrides().size()));if(a!=null){total=a.overrides().size();for(var entry:a.overrides().entrySet().stream().skip(offset).limit(q.size()).toList())rows.add(new Row(UUID.nameUUIDFromBytes((q.player()+"/"+entry.getKey()).getBytes(java.nio.charset.StandardCharsets.UTF_8)),Map.of("policy",entry.getKey(),"override",entry.getValue().name())));}summary.put("recovery",recovery==null||recovery.current()==null?"AVAILABLE":recovery.current().status().name());summary.put("hysteresis",tier==null?"—":tier.tier()+" / revision="+tier.revision()+" / desired="+tier.desiredGroup()+" / sync="+tier.appliedRevision()+"/"+tier.syncRevision());summary.putAll(s.voteSummary(q.player(),q.scope()));summary.put("flags",Long.toString(s.countRecords(Kind.FLAG,q.scope(),q.player(),Filter.empty())-s.countRecords(Kind.FLAG,q.scope(),q.player(),new Filter(null,null,null,"FALSE_POSITIVE",null,null,"","",null))));}
            case VOTE->{var v=s.vote(q.id());if(v==null||!v.scope().equals(q.scope()))throw new IllegalArgumentException("INV_UNKNOWN");rows.add(vote(v));summary.put("uuid",v.targetId().toString());var audits=s.records(Kind.AUDIT,q.scope(),null,v.operationId(),q.size(),offset);for(var a:audits)rows.add(record(a));total=audits.size();}
            case VOTES,PENDING->{Filter f=q.filter();if(q.player()!=null&&f.target()==null)f=new Filter(f.voter(),q.player(),f.type(),f.status(),f.before(),f.after(),f.severity(),f.source(),f.flag(),f.search());if(q.section()==Section.PENDING)f=new Filter(f.voter(),f.target(),f.type(),"PENDING",f.before(),f.after(),f.severity(),f.source(),f.flag(),f.search());if(!f.search().isEmpty()&&!f.scoped())throw new IllegalArgumentException("INV_SCOPE");for(var v:s.select(q.scope(),f,q.size(),offset))rows.add(vote(v));total=s.count(q.scope(),f);}
            case TRUST_HISTORY->{return s.trustHistory(q.player(),q.scope(),q.page(),q.size());}
            case TRUST->{var trust=s.trust(q.player(),q.scope());if(trust!=null){summary.put("model",Integer.toString(trust.modelVersion()));summary.put("calculated",trust.calculatedAt().toString());summary.put("submitted",Long.toString(trust.submitted()));summary.put("invalidated",Long.toString(trust.invalidated()));summary.put("confirmed",Long.toString(trust.confirmed()));summary.put("rehabilitation",InvestigationEngine.decimal(trust.explanation().getOrDefault("rehabilitation_credit",0L)));summary.put("facts_updated",trust.factsAt().toString());summary.put("playtime",Long.toString(trust.playtimeSeconds()));summary.put("first_joined",trust.firstJoined().toString());summary.put("restricted_until",trust.restrictedUntil().toString());summary.put("reliability",InvestigationEngine.decimal(trust.explanation().getOrDefault("invalidated_fraction",0L)));summary.put("maturity",InvestigationEngine.decimal(trust.explanation().getOrDefault("maturity",0L)));summary.put("account_maturity",InvestigationEngine.decimal(Math.min(1000000,Math.max(0,Duration.between(trust.firstJoined(),trust.calculatedAt()).getSeconds())*1000000/((long)s.protection.trust().ageDays()*86400))));summary.put("playtime_maturity",InvestigationEngine.decimal(Math.min(1000000,trust.playtimeSeconds()*1000000/((long)s.protection.trust().playHours()*3600))));var view=s.context(contextVote(q.player(),q.scope(),trust.calculatedAt()),trust.calculatedAt());summary.put("stale",Boolean.toString(trust.inputRevision()<view.scope().revision()||trust.calculatedAt().isBefore(Instant.now().minusSeconds(s.protection.trust().intervalMinutes()*60L))));}}
            case FLAGS->{for(var flag:s.filteredRecords(Kind.FLAG,q.scope(),q.player(),q.filter(),q.size(),offset))rows.add(record(flag));total=s.countRecords(Kind.FLAG,q.scope(),q.player(),q.filter());}
            case RELATIONS->{return relations(q);}
            case ADMIN->{var a=s.administration(q.player(),q.scope());if(a!=null){total=a.audit().size();for(var e:a.audit().reversed().stream().skip(offset).limit(q.size()).toList())rows.add(new Row(e.request().operation(),Map.of("action",e.request().type().name(),"policy",e.request().policy(),"override",e.request().override().name(),"actor",e.request().actor(),"reason",e.request().reason(),"timestamp",e.request().at().toString(),"before",Long.toString(e.previousVisible()),"after",Long.toString(e.resultingVisible()),"contribution",Long.toString(e.resultingAdmin()))));}}
            case RECOVERY->{var r=s.recovery(q.player(),q.scope());if(r!=null){summary.put("recovery",r.current()==null?"AVAILABLE":r.current().status().name());summary.put("recovery_reward",Long.toString(r.lifetimeReward()));summary.put("rehabilitation",InvestigationEngine.decimal(r.lifetimeTrust()));if(r.current()!=null){summary.put("program",r.current().definition().program().id());summary.put("stage",Integer.toString(r.current().stage()+1));summary.put("progress",r.current().progress().toString());}total=r.audit().size();for(var e:r.audit().reversed().stream().skip(offset).limit(q.size()).toList())rows.add(new Row(e.id(),Map.of("action",e.kind(),"actor",e.actor(),"reason",e.reason(),"timestamp",e.at().toString(),"before",e.fromStatus(),"after",e.toStatus())));}}
            case AUDIT->{var records=s.filteredRecords(Kind.AUDIT,q.scope(),q.player(),q.filter(),q.size(),offset);for(var record:records.stream().limit(q.size()).toList())rows.add(record(record));total=s.countRecords(Kind.AUDIT,q.scope(),q.player(),q.filter());}
            case OPERATION->{var a=s.record(Kind.AUDIT,q.id());var b=s.record(Kind.BULK,q.id());if(a!=null&&a.scope().equals(q.scope()))rows.add(record(a));if(b!=null&&b.scope().equals(q.scope()))rows.add(record(b));for(String source:List.of("legacy-admin","legacy-recovery","legacy-protection")){var legacy=s.record(Kind.AUDIT,InvestigationLegacy.id(source,q.id()));if(legacy!=null&&legacy.scope().equals(q.scope()))rows.add(record(legacy));}if(rows.isEmpty()){throw new IllegalArgumentException("INV_UNKNOWN");}total=rows.size();}
            case BULKS->{for(var r:s.records(Kind.BULK,q.scope(),null,null,q.size()+1,offset).stream().limit(q.size()).toList())rows.add(record(r));total=offset+rows.size();}
        }
        if(q.player()!=null&&(q.section()==Section.ADMIN||q.section()==Section.RECOVERY)){
            var enriched=new ArrayList<Row>();for(var row:rows){var v=new TreeMap<>(row.values());v.put("target",q.player().toString());enriched.add(new Row(row.id(),v));}rows=enriched;
        }
        summary.put("page",Integer.toString(q.page()));summary.put("total",Long.toString(total));return new Report(summary,rows,total,InvestigationEngine.hash(List.of(summary,rows)));
    }
    private String uniqueVoters(UUID player,String scope)throws Exception{var votes=s.select(scope,filter(player,null,""),s.rules.relationEvents()+1,0);return (votes.size()>s.rules.relationEvents()?">=":"")+votes.stream().limit(s.rules.relationEvents()).map(VoteEntry::voterId).distinct().count();}
    Row vote(VoteEntry v)throws Exception{var values=new TreeMap<String,String>();values.put("vote",v.operationId().toString());values.put("voter",v.voterId().toString());values.put("target",v.targetId().toString());values.put("action",v.action().name());values.put("type",v.type().name());values.put("reason",v.reason());values.put("comment",v.comment());values.put("timestamp",v.createdAt().toString());values.put("status",s.status(v));values.put("base_weight",Long.toString(v.baseWeight()));values.put("effective_weight",InvestigationEngine.decimal(s.contribution(v)));values.put("model",Integer.toString(v.calculationVersion()));values.put("previous_operation",v.previousOperationId()==null?"—":v.previousOperationId().toString());var a=s.assessment(v.operationId());values.put("revision",Long.toString(InvestigationEngine.moderationRevision(a,s.record(Kind.MODERATION,v.operationId()))));if(a!=null){for(var key:List.of("trust_multiplier","reciprocity_multiplier","repeat_multiplier","diversity_multiplier","maturity_multiplier"))values.put(key,InvestigationEngine.decimal(a.factors().getOrDefault(key,1000000L)));values.put("severity",a.severity().name());values.put("signals",a.signals().toString());}return new Row(v.operationId(),values);}
    record History(Instant time,Row row){}
    static Row trustAudit(Audit a){var values=new TreeMap<String,String>();values.put("action",a.kind());values.put("actor",a.actor());values.put("vote",a.voteId().toString());values.put("timestamp",a.createdAt().toString());values.put("reason",a.reason());values.put("status",a.status().name());values.put("input_revision",Long.toString(a.inputRevision()));if(a.evidence().containsKey("trust_score"))values.put("trust",InvestigationEngine.decimal(a.evidence().get("trust_score")));return new Row(a.id(),values);}
    static Row record(Record r){var values=new TreeMap<>(r.values());values.remove("plan");values.put("count",Integer.toString(r.related().size()));values.put("operation",r.id().toString());values.put("actor",r.actor());values.put("target",r.target().toString());values.put("vote",r.vote().toString());values.put("status",r.status());values.put("revision",Long.toString(r.revision()));values.put("timestamp",r.at().toString());return new Row(r.id(),values);}
    private static Filter filter(UUID target,VoteType type,String status){return new Filter(null,target,type,status,null,null,"","",null);}
    static VoteEntry contextVote(UUID player,String scope,Instant now){return new VoteEntry(InvestigationData.NONE,1,scope,player,player.equals(InvestigationData.NONE)?new UUID(0,1):InvestigationData.NONE,VoteEntry.Action.CAST,VoteType.POSITIVE,"diagnostic","",now,null,1,1,1,"0".repeat(64),0,1);}
    private Report relations(Query q)throws Exception{
        var player=q.player();var votes=new TreeMap<Long,VoteEntry>();for(var v:s.select(q.scope(),new Filter(player,null,null,"",null,null,"","",null),s.rules.relationEvents()+1,0))votes.put(v.sequence(),v);for(var v:s.select(q.scope(),filter(player,null,""),s.rules.relationEvents()+1,0))votes.put(v.sequence(),v);
        boolean complete=votes.size()<=s.rules.relationEvents();var counts=new TreeMap<UUID,long[]>();int work=0;for(var v:votes.descendingMap().values()){if(++work>s.rules.relationEvents()||work>s.rules.graphBudget()){complete=false;break;}if(v.action()==VoteEntry.Action.REVOKE)continue;UUID other=v.voterId().equals(player)?v.targetId():v.voterId();var c=counts.computeIfAbsent(other,id->new long[3]);c[v.voterId().equals(player)?0:1]++;if(v.createdAt().isAfter(Instant.now().minusSeconds(3600)))c[2]++;}
        var rows=counts.entrySet().stream().sorted(Comparator.<Map.Entry<UUID,long[]>>comparingLong(e->e.getValue()[0]+e.getValue()[1]).reversed().thenComparing(e->e.getKey().toString())).limit(s.rules.relationNeighbors()).map(e->new Row(e.getKey(),Map.of("neighbor",e.getKey().toString(),"outgoing",Long.toString(e.getValue()[0]),"incoming",Long.toString(e.getValue()[1]),"reciprocity",Long.toString(Math.min(e.getValue()[0],e.getValue()[1])),"recent_burst",Long.toString(e.getValue()[2]),"evidence","CORRELATION_ONLY"))).toList();
        var graph=s.context(contextVote(player,q.scope(),Instant.now()),Instant.now()).scope();var summary=Map.of("complete",Boolean.toString(complete),"examined",Integer.toString(work),"evidence","CORRELATION_ONLY","clusters",Long.toString(graph.clusters().stream().filter(group->group.contains(player)).count()),"graph_complete",Boolean.toString(graph.graphComplete()));return new Report(summary,rows.subList((int)Math.min(rows.size(),((long)q.page()-1)*q.size()),(int)Math.min(rows.size(),(long)q.page()*q.size())),rows.size(),InvestigationEngine.hash(List.of(summary,rows)));
    }
    static Record flag(Assessment a,String source){return new Record(InvestigationEngine.flagId(a.voteId(),source),Kind.FLAG,a.scope(),"SYSTEM",a.target(),a.voteId(),a.status()==Status.PENDING?"PENDING_REVIEW":"SUSPICION",1,a.evaluatedAt(),Map.of("source",source,"severity",a.severity().name(),"voter",a.voter().toString(),"created",a.evaluatedAt().toString(),"evidence",a.factors().toString()),List.of(a.voteId()));}
}
